* {
  margin: 0;
  border: 0;
  padding: 0;
  font-family: "coolvetica";
}

body {
  overflow-x: hidden;
  background-color: var(--bgclr);
}

main {
  width: 100vw;
}

/* --------------------------INDEX PAGE CSS------------------------------ */
nav {
  /* border: 2px solid red; */
  height: auto;
  position: fixed;
  top: 0;
  width: 100vw;
  left: 0;
  padding: 10px;
  display: flex;
  flex-direction: row;
  background-color: var(--navbar);
  z-index: 100;
}

.nav_logo {
  display: flex;
  height: var(--nav_height);
  width: 50%;
  align-items: center;
  /* justify-content: center; */
}

/* .logo {
  display: inline;
  margin-left: 30px;
  } */
.logo a {
  margin-left: 20px;
  font-size: 50px;
  text-decoration: none;
  color: white;

  font-family: "coolvetica";
}

.nav_links {
  display: flex;
  align-items: center;
  justify-content: space-evenly;
  width: 45%;
  overflow: hidden;
  /* padding-left:-20px; */
}

.nav_link_item {
  display: inline;
  color: white;
  text-decoration: none;
  width: 25%;
  text-align: center;
  padding: 10px;
  background-color: hsl(0, 0%, 10%);
  margin: 0 20px;
  /* border: 2px solid grey; */
  font-size: 20px;
  border-radius: var(--border-radius);
  font-family: "coolvetica";
  transition: 0.5s;
}

.nav_link_item:hover {
  background-color: hsl(0, 0%, 20%);
  color: white;
  /* transform: scale(1.05); */
  /* box-shadow: 0 4px 12px -6px var(--primary); */
}

.hero {
  display: flex;
  height: calc(100vh);
  flex-direction: column;
  justify-content: center;
  /* align-items: center; */
  background-image: url("content/bgm.jpg");
  opacity: 100%;
  background-repeat: no-repeat;
  background-position: center;
  background-size: cover;
  z-index: -1;
  width: 100vw;


}

.hero_big {
  font-size: 100px;
  margin-bottom: 5vh;
  width: 100vw;
  color: rgb(33, 33, 33);
  font-family: "coolvetica";
  text-align: center;
}

.hero_small {
  font-size: 40px;
  color: rgb(33, 33, 33);
  text-align: center;
  font-family: "coolvetica";
}

.hero_button {
  display: inline-block;
  text-decoration: none;
  text-align: center;
  color: rgb(33, 33, 33);
  border: 2px solid white;
  padding: 15px 0;
  font-size: 25px;
  margin: 10vh 30vw 0 30vw;
  width: 40vw;
  border-radius: var(--border-radius-small);
  font-family: "coolvetica";
}

main {
  padding-top: 50px;
}

.product-list {
  display: flex;
  flex-wrap: wrap;
  gap: 15px;
  justify-content: center;
  margin: 40px 0;
}

.ft_summer {
  width: 100%;
  font-weight: 500;
  font-size: 70px;
  margin-top: 50px;
  margin-bottom: 20px;
  text-align: center;
  font-family: "coolvetica";
}

.product-card h3,
.product-card p,
.product-info .back-link,
.product-info .price,
.product-info h2,
.sold-out-overlay {
  font-family: coolvetica;
}

.product-card a img {
  transition: transform 0.2s;
  /* height:75%; */
}

.product-card {
  max-width: 400px;

  buy-detail,
  .main-image {
    /* border-radius: var(--border-radius); */
    /* box-shadow: 0 2px 16px -8px var(--primary); */
  }

  .main-image-container {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
  }

  .main-image {
    height: 100%;
    object-fit: fill;
    opacity: 1;
    transition: opacity 0.4s;
  }

  .img-wrapper img,
  .sold-out-overlay {
    width: 100%;
    /* border-radius: var(--border-radius-small); */
  }

  .main-image.fade-in {
    opacity: 0;
    animation: 0.4s forwards fadeInImg;
  }

  @keyframes fadeInImg {
    from {
      opacity: 0;
    }

    to {
      opacity: 1;
    }
  }

  .product-info {
    flex: 1;
    /* padding-left: 32px; */
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
  }

  .product-info h2 {
    font-size: 2.5rem;
    margin-bottom: 12px;
    color: var(--textclrprimary);
    font-weight: 400;
  }

  .product-info .price {
    color: var(--secondary1);
    font-size: 2rem;
    margin-bottom: 16px;
  }

  .product-info .product-description {
    color: var(--textclrprimary);
    font-size: 0.5rem;
    margin-bottom: 24px;
  }

  .product-info .back-link {
    color: var(--primary);
    text-decoration: none;
    font-size: 1.5rem;
    margin-top: 16px;
    transition: color 0.2s;
    font-weight: 500;
  }

  .img-wrapper {
    display: inline-block;
    width: 100%;
  }

  .img-wrapper img {
    display: block;
    transition: filter 0.3s;
  }

  .img-wrapper.out-of-stock img {
    filter: brightness(0.4) grayscale(0.2);
  }

  .sold-out-overlay {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    background: hsla(0, 0%, 25%, 25%);
    color: var(--sold-out);
    font-weight: 500;
    font-size: 2rem;
  }

  #buy-detail h2,
  .buy-now-btn,
  .coming_soon {
    color: var(--textclrprimary);
  }

  .buy-now-btn:hover {
    box-shadow: 0 4px 12px -6px var(--primary);
    transform: scale(1.01);
    box-shadow: 0 4px 12px -6px var(--primary);
  }

  #buy-detail {
    max-width: 620px;
    margin: 48px auto 32px;
    background: var(--bgsecondary);
    padding: 32px 24px;
  }

  #buy-detail h2 {
    font-size: 2.2rem;
    font-family: coolvetica, sans-serif;
    font-weight: 500;
    margin-bottom: 18px;
  }

  #buy-detail p,
  .buy-now-btn {
    font-size: 2rem;
    font-family: coolvetica, sans-serif;
  }

  #buy-detail img {
    width: 90%;
    height: auto;
    border-radius: var(--border-radius-small);
    margin-bottom: 18px;
    box-shadow: 0 2px 12px -6px var(--secondary1);
  }

  #buy-detail p {
    color: var(--secondary1);
    margin-bottom: 24px;
    font-size: 2.2rem;
  }

  #buy-detail form {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 14px;
    margin-top: 12px;
  }

  #buy-detail input[type="email"],
  #buy-detail input[type="text"],
  #buy-detail input[type="tel"] {
    width: 90%;
    padding: 10px 14px;
    font-size: 1.1rem;
    border-radius: 8px;
    border: 1.5px solid var(--secondary1);
    font-family: coolvetica, sans-serif;
    margin-bottom: 0;
    background: var(--bgprimary);
    color: var(--textclrprimary);
    transition: border 0.2s;
  }

  #buy-detail input[type="email"]:focus,
  #buy-detail input[type="text"]:focus {
    border: 2px solid var(--primary);
    outline: 0;
  }

  .buy-now-btn {
    background: var(--primary-dark);
    box-shadow: 0 2px 8px -4px var(--primary);
    display: inline-block;
    margin-top: 10px;
    padding: 12px 32px;
    background: var(--primary-dark);
    font-weight: 500;
    border: none;
    border-radius: 8px;
    cursor: pointer;
    text-decoration: none;
    transition: background 0.2s, transform 0.2s;
    box-shadow: 0 2px 8px -4px var(--primary);
  }

  .coming_soon {
    height: 90vh;
    margin-top: 100px;
    padding: 20px;
    font-family: coolvetica;
    font-size: 55px;
  }

  color: var(--textclrprimary);
  width: 25%;
  padding: 20px 10px;
  transition: transform 0.2s,
  box-shadow 0.2s;
  /* border: 2px solid rgb(105, 105, 105); */
  border-radius: var(--border-radius-small);
  /* box-shadow: 0 12px 16px 8px rgb(141, 141, 141); */
  background-color:rgb(255, 255, 255);

}

.product-card a {
  text-decoration: none;
  color: var(--textclrprimary);
  display: flex;
  flex-direction: column;
  height: 100%;
}

.product-card:hover {
  transform: translateY(-6px) scale(1.03);
  box-shadow: 0 5px 20px -10px black;
}

.product-card img {
  width: 100%;
  object-fit: cover;
  border-radius: 8px;
  margin-top: -8px;
}

.product-card h3 {
  margin: 16px 0 8px;
  font-size: 2.5rem;
  color: var(--textclrprimary);
  font-weight: 500;
}

.product-card p {
  color: var(--secondary1);
  font-size: 2rem;
  font-weight: 500;
  margin-top: auto;
}

.product-card .product-description {
  color: var(--textclrsecondary);
  font-size: 1rem;
  font-family: coolvetica;
  margin: 8px 0;
}

.product_price,
.price {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-items: baseline;
  justify-content: center;
  margin-bottom: 10px;
}

.original-price {
  color: #d52b1e;
  font-size: 1rem;
  text-decoration: line-through dashed #d52b1e;
  border-bottom: 1px dashed #d52b1e;
  padding-bottom: 2px;
  opacity: 0.9;
}

.discounted-price {
  color: var(--secondary1);
  font-size: 2rem;
  font-weight: 700;
}

.product-detail {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.product-gallery {
  display: flex;
  gap: 40px;
  align-items: flex-start;
  margin: 40px;
  max-width: 900px;
  /* border-radius: var(--border-radius); */
  /* box-shadow: 0 2px 16px -8px var(--bgclrdark); */
  padding: 32px 24px;
  flex-direction: column;
  flex-wrap: wrap;
  /* border: 2px solid var(--bgclrcontentdark); */
}

.thumbnails {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  width: 100%;
  max-width: 100%;
  margin-bottom: 24px;
  padding: 8px;
  gap: 16px;
}

.thumbnails img.thumbnail,
.thumbnails video.thumbnail {
  width: 70px;
  height: 70px;
  object-fit: cover;
  border-radius: 8px;
  cursor: pointer;
  border: 2px solid transparent;
  transition: border 0.2s, box-shadow 0.2s;
  box-shadow: 0 1px 6px -2px var(--primary);
}

.thumbnails img.thumbnail.selected,
.thumbnails video.thumbnail.selected {
  border: 2px solid var(--secondary1);
  box-shadow: 0 2px 12px -4px var(--secondary1);
}

.main-media {
  width: 100%;
  object-fit: contain;
  opacity: 1;
  transition: opacity 0.4s;
  max-height: 650px;
}

.main-media.fade-in {
  opacity: 0;
  animation: 0.4s forwards fadeInImg;
  box-shadow: none;
  border-radius: 10px;
}

footer {
  display: flex;
  width: 100%;
  height: 200px;
  border-top: 4px solid var(--footer-border);
  margin-top: 100px;
  flex-direction: row;
  align-items: center;
  flex-wrap: wrap;
  justify-content: space-between;
  flex-direction: row;
  flex-wrap: nowrap;
  align-items: center;
  /* justify-content: center; */
}

.footer_logo {
  margin-left: 30px;
  width: 20%;
  text-align: left;
  margin-top: 25px;
  font-size: 90px;
  color: var(--textclrprimary);
  font-family: coolvetica;
}

#buy-detail,
.buy-now-btn,
.ft_summer,
.product-card {
  text-align: center;
}

.footer_logo p {
  font-size: 15px;
  text-align: left;
  color: var(--textclrsecondary);
  margin-bottom: var(--marginbasic);
}

.footer_link p,
.ft_summer {
  font-family: moela;
  color: var(--textclrprimary);
}

.footer_link {
  display: flex;
  width: 50%;
  height: 100%;
  flex-wrap: wrap;
  flex-direction: row;
}

.footer_link p {
  font-size: 45px;
  width: 100%;
  margin-top: 25px;
  margin-bottom: auto;
}

.footer_links {
  width: 20%;
  display: flex;
  flex-direction: row;
  align-items: flex-start;
}

.footer_links img {
  width: 50px;
}

buy-detail,
.main-image,
.main-media {
